-- E5 · Carres-only maintenance entries, each added only when the database lacks it when this runs
--   not loaded, kept in the workbook: leg height "6" / No Leg" (sofa default leg): not one value; sofa leg is chosen on the SO line
--   not loaded, kept in the workbook: total height 48" (HB 48"): headboard height, not the engine's Total Height measure - confirm first
--   not loaded, kept in the workbook: total height 50" (HB 50"): headboard height, not the engine's Total Height measure - confirm first
--   not loaded, kept in the workbook: total height 52" (HB 52"): headboard height, not the engine's Total Height measure - confirm first
--   not loaded, kept in the workbook: divan 10" on CODY-(K): +RM50 supplier cost, kept in the workbook (no per-SKU divan cost field)
--   not loaded, kept in the workbook: divan 12" on CODY-(K): +RM120 supplier cost, kept in the workbook (no per-SKU divan cost field)
--   not loaded, kept in the workbook: divan 10" on CODY-(Q): +RM50 supplier cost, kept in the workbook (no per-SKU divan cost field)
--   not loaded, kept in the workbook: divan 12" on CODY-(Q): +RM120 supplier cost, kept in the workbook (no per-SKU divan cost field)
--   not loaded, kept in the workbook: divan 10" on CODY-(S): +RM50 supplier cost, kept in the workbook (no per-SKU divan cost field)
--   not loaded, kept in the workbook: divan 12" on CODY-(S): +RM120 supplier cost, kept in the workbook (no per-SKU divan cost field)
do $maint$
declare
  co bigint := (select id from public.companies where code = 'HOUZS');
  cfg jsonb; pool jsonb; changed boolean := false; c record;
begin
  select config into cfg from scm.maintenance_config_history
   where company_id = co and scope = 'master' and effective_from <= current_date order by effective_from desc, created_at desc limit 1;
  cfg := coalesce(cfg, '{}'::jsonb);
  for c in select * from (values
    (1, 'sofaCompartments', '"1A(LHF)"'::jsonb, '1A(LHF)', true),
    (2, 'sofaCompartments', '"1A(RHF)"'::jsonb, '1A(RHF)', true),
    (3, 'sofaCompartments', '"1NA"'::jsonb, '1NA', true),
    (4, 'sofaCompartments', '"1S"'::jsonb, '1S', true),
    (5, 'sofaCompartments', '"2A(LHF)"'::jsonb, '2A(LHF)', true),
    (6, 'sofaCompartments', '"2A(RHF)"'::jsonb, '2A(RHF)', true),
    (7, 'sofaCompartments', '"2NA"'::jsonb, '2NA', true),
    (8, 'sofaCompartments', '"2S"'::jsonb, '2S', true),
    (9, 'sofaCompartments', '"3S"'::jsonb, '3S', true),
    (10, 'sofaCompartments', '"CNR"'::jsonb, 'CNR', true),
    (11, 'sofaCompartments', '"CNR(BIG)"'::jsonb, 'CNR(BIG)', true),
    (12, 'sofaCompartments', '"CNR(SMALL)"'::jsonb, 'CNR(SMALL)', true),
    (13, 'sofaCompartments', '"CONSOLE"'::jsonb, 'CONSOLE', true),
    (14, 'sofaCompartments', '"CONSOLE WOODEN"'::jsonb, 'CONSOLE WOODEN', true),
    (15, 'sofaCompartments', '"DB"'::jsonb, 'DB', true),
    (16, 'sofaCompartments', '"HEADREST"'::jsonb, 'HEADREST', true),
    (17, 'sofaCompartments', '"L(LHF)"'::jsonb, 'L(LHF)', true),
    (18, 'sofaCompartments', '"L(RHF)"'::jsonb, 'L(RHF)', true),
    (19, 'sofaCompartments', '"STOOL"'::jsonb, 'STOOL', true),
    (20, 'sofaSizes', '"24"'::jsonb, '24', false),
    (21, 'sofaSizes', '"26"'::jsonb, '26', false),
    (22, 'sofaSizes', '"28"'::jsonb, '28', false),
    (23, 'sofaSizes', '"30"'::jsonb, '30', false),
    (24, 'sofaSizes', '"32"'::jsonb, '32', false),
    (25, 'sofaSizes', '"35"'::jsonb, '35', false),
    (26, 'sofaSizes', '"DEFAULT"'::jsonb, 'DEFAULT', false),
    (27, 'divanHeights', '{"value":"10\"","priceSen":0}'::jsonb, '10"', false),
    (28, 'divanHeights', '{"value":"12\"","priceSen":0}'::jsonb, '12"', false),
    (29, 'gaps', '"12\""'::jsonb, '12"', false),
    (30, 'gaps', '"14\""'::jsonb, '14"', false),
    (31, 'gaps', '"16\""'::jsonb, '16"', false),
    (32, 'legHeights', '{"value":"1\"","priceSen":0}'::jsonb, '1"', false),
    (33, 'specials', '{"value":"FBF","priceSen":0}'::jsonb, 'FBF', false),
    (34, 'specials', '{"value":"HB Straight","priceSen":0}'::jsonb, 'HB Straight', false),
    (35, 'bedframeSizes', '"S"'::jsonb, 'S', false),
    (36, 'bedframeSizes', '"SS"'::jsonb, 'SS', false),
    (37, 'bedframeSizes', '"Q"'::jsonb, 'Q', false),
    (38, 'bedframeSizes', '"K"'::jsonb, 'K', false),
    (39, 'bedframeSizes', '"SK"'::jsonb, 'SK', false),
    (40, 'bedframeSizes', '"SP"'::jsonb, 'SP', false)
  ) v(ord, pool_name, elem, k, unless_compartment) order by ord loop
    if c.unless_compartment and exists (select 1 from scm.compartment_library where company_id = co and lower(btrim(regexp_replace(label, '\s+', ' ', 'g'))) = lower(btrim(regexp_replace(c.k, '\s+', ' ', 'g')))) then
      continue;
    end if;
    pool := case when jsonb_typeof(cfg -> c.pool_name) = 'array' then cfg -> c.pool_name else '[]'::jsonb end;
    continue when exists (select 1 from jsonb_array_elements(pool) e(x)
      where lower(btrim(regexp_replace(case jsonb_typeof(e.x) when 'string' then e.x #>> '{}' else e.x ->> 'value' end, '\s+', ' ', 'g'))) = lower(btrim(regexp_replace(c.k, '\s+', ' ', 'g'))));
    cfg := jsonb_set(cfg, array[c.pool_name], pool || jsonb_build_array(c.elem));
    changed := true;
    raise notice 'Carres master data: maintenance % + %', c.pool_name, c.k;
  end loop;
  if changed then
    insert into scm.maintenance_config_history (id, company_id, scope, config, effective_from, notes)
    values (gen_random_uuid()::text, co, 'master', cfg, current_date, 'Carres master data: Carres-only entries');
  end if;
end $maint$;
