  and regexp_replace(upper(coalesce('CX1211', '')), '[^A-Z0-9]', '', 'g') in (regexp_replace(upper(coalesce(id, '')), '[^A-Z0-9]', '', 'g'), regexp_replace(upper(coalesce(label, '')), '[^A-Z0-9]', '', 'g'), regexp_replace(upper(coalesce(fabric_code, '')), '[^A-Z0-9]', '', 'g')))
